// Hidden extra for the node-tar negative-size task (run after `npm run prepare`).
import assert from 'node:assert/strict';
import { pathToFileURL } from 'node:url';
import { join } from 'node:path';

const dir = process.cwd();
const { Header } = await import(pathToFileURL(join(dir, 'dist/esm/header.js')));
const { Pax } = await import(pathToFileURL(join(dir, 'dist/esm/pax.js')));
const large = await import(pathToFileURL(join(dir, 'dist/esm/large-numbers.js')));

// A raw header block whose size field holds a base-256 negative number.
const good = new Header({ path: 'x', type: 'File', size: 10, mode: 0o644, mtime: new Date(0) });
good.encode();
const block = Buffer.from(good.block);
large.encode(-1000, block.subarray(124, 136));
assert.equal(new Header(block).size, undefined, 'negative size in the block');

// Extended-header sizes: a negative or non-numeric one is never taken.
assert.equal(new Header(block, 0, { size: -5 }).size, undefined, 'negative ex size');
assert.equal(new Header(Buffer.from(good.block), 0, { size: 42 }).size, 42, 'ex size wins');
assert.equal(new Header(Buffer.from(good.block)).size, 10, 'block size kept');

// Zero is a valid size everywhere.
assert.equal(new Header({ size: 0 }).size, 0);
assert.equal(Pax.parse('10 size=0\n').size, 0);
assert.equal(Pax.parse('11 size=-1\n').size, undefined);
assert.equal(Pax.parse('12 size=abc\n').size, undefined);
// Other numeric pax fields are unchanged.
assert.equal(Pax.parse('10 uid=-1\n').uid, -1);
assert.equal(Pax.parse('12 mtime=10\n').mtime.getTime(), 10000);

console.log('tar negative size extra passed');

