import assert from "node:assert/strict";
import { parseDocument } from "htmlparser2";

// The built package (`npm run build` writes dist).
const { selectAll } = await import(
    new URL("../../dist/index.js", import.meta.url).href
);

const dom = parseDocument(
    '<div lang="en-US"><p id="a">A</p></div><p id="b" lang="fr">B</p><p id="c">C</p>',
);

// A range matches its own tag and longer tags, inherited from ancestors.
const ids = selectAll("p:lang(en)", dom).map((element) => element.attribs.id);
assert.deepEqual(ids, ["a"]);

console.log("visible check passed");

import { readFileSync } from 'node:fs'
import assert from 'node:assert/strict'
import * as JSON5 from '../../lib/index.js'

const source = readFileSync(new URL('../../lib/parse.js', import.meta.url), 'utf8')
// The parse-state table is gone.
assert.equal((source.match(/^const parseStates\b/gm) ?? []).length, 0, 'lib/parse.js still declares parseStates')

// Parsing is unchanged.
assert.deepEqual(JSON5.parse("{a: [1, 'two', {b: null}], c: +Infinity,}"), { a: [1, 'two', { b: null }], c: Infinity })
assert.throws(() => JSON5.parse('{a: 1'), /invalid end of input/)

console.log('visible check passed')

import { readFileSync } from "node:fs";
import assert from "node:assert/strict";

const package_ = JSON.parse(readFileSync(new URL("../../package.json", import.meta.url), "utf8"));
assert.equal(package_.devDependencies.htmlparser2, "12.0.0", package_.devDependencies.htmlparser2);
const lock = JSON.parse(readFileSync(new URL("../../package-lock.json", import.meta.url), "utf8"));
assert.equal(lock.packages["node_modules/htmlparser2"].version, "12.0.0");
assert.equal(lock.packages[""].devDependencies.htmlparser2, "12.0.0");
const installed = JSON.parse(readFileSync(new URL("../../node_modules/htmlparser2/package.json", import.meta.url), "utf8"));
assert.equal(installed.version, "12.0.0");

console.log("visible check passed");

