// Hidden effect check for the htmlparser2 12 upgrade: run against the project's sources through
// vitest-free node, using the installed htmlparser2 the tests build their fixtures with.
import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';

const dir = process.cwd();
const require = createRequire(join(dir, 'package.json'));
const { parseDocument } = await import(pathToFileURL(require.resolve('htmlparser2')));
// htmlparser2 12 rewrites <image> to <img> outside foreign content and treats
// <iframe> content as raw text; 11 did neither.
const dom = parseDocument('<p><image src="a.png"><iframe><b>x</b></iframe></p>');
const tags = [];
(function walk(nodes) { for (const n of nodes) { if (n.type === 'tag') tags.push(n.name); if (n.children) walk(n.children); } })(dom.children);
assert.deepEqual(tags, ['p', 'img', 'iframe'], `parsed tags ${tags.join(',')}`);
console.log('htmlparser2 12 effect check passed');

